-- 2026-11-02_서버_별칭.sql  (필수, 데이터 수정)
--
-- corpus.item_alias 의 '서버' → 기계장치 별칭을 지우고 '서버 임차' → 지급수수료 별칭을 넣는다.
--
-- 왜
--   통합관리지침 제39조①은 기계장치를 기계·설비를 "구매하는 비용"으로, 제42조⑦은 기자재임차비(지급수수료)를
--   "기기, 장비, 부수 기자재, 서버 등을 임차하는 경비"로 정한다. 같은 지침 제47조⑧과 창업중심대학 참고5,
--   초격차 참고3 도 "서버 임차"를 따로 적는다. 그래서 '서버' 하나로는 비목이 정해지지 않는다.
--   지우는 행의 출처는 초격차 참고2 허용예시인데, 원문은 "클라우드 서버 구축용 장비"이고 그 별칭(같은 원문)은 그대로 둔다.
--   '서버' 별칭은 정규화 프롬프트의 별칭 힌트(부분 문자열 일치)에 "서버 -> 기계장치"로 들어가, AWS·클라우드 서버
--   이용료 질문(골든 v2 정답: 지급수수료)을 기계장치로 분류하게 했다.
--   새 행의 원문발췌는 지침 제42조⑦ 원문 그대로다. 임베딩은 KURE-v1(rule_lookup.임베딩, 정규화)로 '서버 임차'를 계산했다.
--
-- 멱등: 다시 실행해도 같은 상태가 된다. 지운 행은 backup_dq_20261102.item_alias 에 남긴다.
-- 실행 (운영, deploy/ncp): ./backup.sh 후
--   docker compose exec -T db psql -U postgres -d suddoe -X -v ON_ERROR_STOP=1 -f - < ../../db/migrations/2026-11-02_서버_별칭.sql

\set ON_ERROR_STOP on
BEGIN;
CREATE SCHEMA IF NOT EXISTS backup_dq_20261102;
REVOKE ALL ON SCHEMA backup_dq_20261102 FROM PUBLIC;
CREATE TABLE IF NOT EXISTS backup_dq_20261102.item_alias (LIKE corpus.item_alias);
INSERT INTO backup_dq_20261102.item_alias
SELECT a.* FROM corpus.item_alias a
 WHERE a."품목" = '서버' AND a."사업명" IS NULL AND a."비목" = '기계장치'
   AND NOT EXISTS (SELECT 1 FROM backup_dq_20261102.item_alias b WHERE b.alias_id = a.alias_id);
DELETE FROM corpus.item_alias WHERE "품목" = '서버' AND "사업명" IS NULL AND "비목" = '기계장치';
