        '“기자재임차비”는 해당 아이템 개발을 위해 사용할 수 있는 기기, 장비, 부수 기자재, 서버 등을 임차하는 경비를 의미한다.', 'L1_중소기업창업_지원사업_통합관리지침_제14차개정_20251223', '제42조')
ON CONFLICT ("품목", "사업명") DO UPDATE
   SET "비목" = EXCLUDED."비목", "출처" = EXCLUDED."출처", embedding = EXCLUDED.embedding,
       "원문발췌" = EXCLUDED."원문발췌", doc_id = EXCLUDED.doc_id, "조번호" = EXCLUDED."조번호";
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM corpus.item_alias WHERE "품목" = '서버' AND "사업명" IS NULL) THEN
    RAISE EXCEPTION '서버 별칭이 남아 있다';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM corpus.item_alias WHERE "품목" = '서버 임차' AND "비목" = '지급수수료' AND embedding IS NOT NULL) THEN
    RAISE EXCEPTION '서버 임차 별칭이 없다';
  END IF;
  -- 원문발췌가 지침 제42조 본문에 그대로 있는지 확인한다
  IF NOT EXISTS (SELECT 1 FROM corpus.doc_articles a JOIN corpus.documents d USING (doc_id)
                  WHERE d.doc_id = 'L1_중소기업창업_지원사업_통합관리지침_제14차개정_20251223' AND d.status = 'active'
                    AND a."조번호" = '제42조'
                    AND regexp_replace(a."본문", '\s+', '', 'g') LIKE '%' || regexp_replace('“기자재임차비”는 해당 아이템 개발을 위해 사용할 수 있는 기기, 장비, 부수 기자재, 서버 등을 임차하는 경비를 의미한다.', '\s+', '', 'g') || '%') THEN
    RAISE EXCEPTION '원문발췌가 지침 제42조 본문과 맞지 않는다';
  END IF;
  RAISE NOTICE '서버 별칭: 확인 통과';
END $$;
COMMIT;
